// pageEditPreviewFixture is the agent's page-edit precheck, generated by
// PageEditRouterTest through the signed Router.
type pageEditPreviewFixture struct {
	RequestID       string          `json:"request_id"`
	EntrySHA256     string          `json:"entry_sha256"`
	Input           string          `json:"input"`
	BaseFingerprint string          `json:"base_fingerprint"`
	Preview         json.RawMessage `json:"preview"`
	TreeJSON        string          `json:"tree_json"`
	PreviewDigest   string          `json:"preview_digest"`
	PrecheckDigest  string          `json:"precheck_digest"`
}

func readPageEditPreviewFixture(t *testing.T) pageEditPreviewFixture {
	t.Helper()
	raw, err := os.ReadFile(agentAbilityFixtures + "page-edit-preview.json")
	if err != nil {
		t.Fatalf("read the agent's page-edit preview fixture: %v", err)
	}
	var fx pageEditPreviewFixture
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatalf("decode the fixture: %v", err)
	}
	if fx.Input == "" || len(fx.Preview) == 0 || fx.TreeJSON == "" {
		t.Fatal("the fixture carries no input, preview or tree_json")
	}
	return fx
}

// fixtureResponse is the precheck answer the fixture recorded, with the
// preview replaced by preview when it is not nil.
func fixtureResponse(fx pageEditPreviewFixture, preview json.RawMessage) agentcmd.AbilityRunResponse {
	if preview == nil {
		preview = fx.Preview
	}
	return agentcmd.AbilityRunResponse{
		OK: true, Outcome: "prechecked", Mode: "precheck", Ability: AbilityPageEdit,
		RequestID: fx.RequestID, Valid: true, BaseFingerprint: fx.BaseFingerprint,
		PreviewDigest: fx.PreviewDigest, PrecheckDigest: fx.PrecheckDigest, Preview: preview,
	}
}

func fixtureFacts(t *testing.T, fx pageEditPreviewFixture) pageEditFacts {
	t.Helper()
	f, code := validatePageEditInput([]byte(fx.Input))
	if code != "" {
		t.Fatalf("the fixture's input is refused: %s", code)
	}
	return f
}

// TestPageEditPreviewFixtureBinds replays the agent's precheck: the tree
// re-encodes to the agent's canonical bytes, both digests recompute, and the
// outline after the edit is the one the control plane projects.
func TestPageEditPreviewFixtureBinds(t *testing.T) {
	fx := readPageEditPreviewFixture(t)
	f := fixtureFacts(t, fx)
	var pv pageEditPreview
	if err := json.Unmarshal(fx.Preview, &pv); err != nil {
		t.Fatal(err)
	}
	tree, ok := phpDecodeDocument(pv.Tree, pageEditTreeMaxDepth, true)
	if !ok {
		t.Fatal("the preview tree does not decode")
	}
	got, ok := phpEncodeBytes(tree)
	if !ok || string(got) != fx.TreeJSON {
		t.Fatalf("tree bytes differ from the agent's canonical bytes:\n got %s\nwant %s", got, fx.TreeJSON)
	}
	checked, ok := verifyPageEditPrecheck(fixtureResponse(fx, nil), fx.EntrySHA256, []byte(fx.Input), f)
	if !ok {
		t.Fatal("the agent's own precheck does not bind to its input")
	}
	if checked.postID != f.postID || checked.previewDigest != fx.PreviewDigest || len(checked.changes) != len(f.ops) {
		t.Fatalf("checked facts: %+v", checked)
	}
	card, err := buildPageEditCardFacts(checked, time.Date(2026, 10, 9, 12, 0, 0, 0, time.UTC))
	if err != nil {
		t.Fatal(err)
	}
	read, ok := ReadPageEditCardFacts(card)
	if !ok || read.Kind != PageEditCardKind || read.Post.ID != f.postID || read.AfterOutlineOmitted ||
		len(read.AfterOutline) == 0 || len(read.Changes) != len(f.ops) {
		t.Fatalf("card facts: %s", card)
	}
	if read.Post.FromTheSite.Title != pv.Title || read.Builder.ID != "elementor" || read.Builder.Version != pv.BuilderVersion {
		t.Fatalf("card post and builder: %s", card)
	}
}

// mutatePreview decodes the fixture's preview, lets edit change it, and
// returns it with tree_sha256 and both digests recomputed for the edited
// tree, so only the check under test can refuse it.
func mutatePreview(t *testing.T, fx pageEditPreviewFixture, edit func(pv map[string]any)) (agentcmd.AbilityRunResponse, []byte) {
	t.Helper()
	dec := json.NewDecoder(bytes.NewReader(fx.Preview))
	dec.UseNumber()
	var pv map[string]any
	if err := dec.Decode(&pv); err != nil {
		t.Fatal(err)
	}
	edit(pv)
	treeRaw, err := json.Marshal(pv["tree"])
	if err != nil {
		t.Fatal(err)
	}
	tree, ok := phpDecodeDocument(treeRaw, pageEditTreeMaxDepth, true)
	if !ok {
		t.Fatal("the edited tree does not decode")
	}
	treeJSON, _ := phpEncodeBytes(tree)
	pv["tree_sha256"] = sha256Hex(treeJSON)
	version, _ := pv["builder_version"].(string)
	digest, _ := pageEditPreviewDigest("elementor", version, 120, fx.BaseFingerprint, treeJSON)
	preview, err := json.Marshal(pv)
	if err != nil {
		t.Fatal(err)
	}
	resp := fixtureResponse(fx, preview)
	resp.PreviewDigest = digest
	pre, _ := phpJSONStringArray(fx.EntrySHA256, sha256Hex([]byte(fx.Input)), fx.BaseFingerprint, digest)
	resp.PrecheckDigest = sha256Hex(pre)
	return resp, treeJSON
}

// recomputeOutline sets after_outline to the control plane's projection of
// the preview's tree, so a case reaches the checks after it.
func recomputeOutline(pv map[string]any) {
	raw, _ := json.Marshal(pv["tree"])
	tree, _ := phpDecodeDocument(raw, pageEditTreeMaxDepth, true)
	proj, err := elementorProject(tree)
	if err != nil {
		panic(err)
	}
	after, _ := proj.answer(pageStructureMaxNodes, pageStructureMaxBytes)
	pv["after_outline"], _ = projectionJSON(after)
}

// findWidget is the element with id in a decoded tree.
func findWidget(list []any, id string) map[string]any {
	for _, n := range list {
		m, _ := n.(map[string]any)
		if m == nil {
			continue
		}
		if m["id"] == id {
			return m
		}
		if children, ok := m["elements"].([]any); ok {
			if found := findWidget(children, id); found != nil {
				return found
			}
		}
	}
	return nil
}

// TestPageEditPrecheckRefusesWhatDoesNotBind: each answer differs from the
// agent's own in one way and is refused, every digest recomputed so only
// the check named can refuse it.
func TestPageEditPrecheckRefusesWhatDoesNotBind(t *testing.T) {
	fx := readPageEditPreviewFixture(t)
	f := fixtureFacts(t, fx)
	input := []byte(fx.Input)
	// The control: recomputing every digest over an unchanged preview binds.
	if resp, _ := mutatePreview(t, fx, func(map[string]any) {}); !verifyOK(resp, fx, input, f) {
		t.Fatal("the recomputed, unchanged preview must bind")
	}
	cases := map[string]func(pv map[string]any){
		"set_text after is not the input's text": func(pv map[string]any) {
			c := pv["changes"].([]any)[0].(map[string]any)
			c["after"] = map[string]any{"text": "Something else"}
		},
		"a change is missing": func(pv map[string]any) {
			pv["changes"] = pv["changes"].([]any)[:1]
		},
		"the insert names another anchor": func(pv map[string]any) {
			a := pv["changes"].([]any)[1].(map[string]any)["anchor"].(map[string]any)
			a["ref"] = "52982f9"
		},
		"the inserted paragraph holds other text": func(pv map[string]any) {
			w := findWidget(pv["tree"].([]any), "82e3b4f")
			w["settings"].(map[string]any)["editor"] = "<p>Not what was asked</p>"
			recomputeOutline(pv)
		},
		"the inserted node is an HTML widget": func(pv map[string]any) {
			w := findWidget(pv["tree"].([]any), "82e3b4f")
			w["widgetType"] = "html"
			w["settings"] = map[string]any{"html": "<script></script>"}
			recomputeOutline(pv)
		},
		"the set_text target's text in the tree is not the input's": func(pv map[string]any) {
			w := findWidget(pv["tree"].([]any), "52982f9")
			w["settings"].(map[string]any)["title"] = "Other title"
			recomputeOutline(pv)
		},
		"after_outline is not the tree's projection": func(pv map[string]any) {
			nodes := pv["after_outline"].(map[string]any)["nodes"].([]any)
			pv["after_outline"].(map[string]any)["nodes"] = nodes[:len(nodes)-1]
		},
		"another post": func(pv map[string]any) {
			pv["post_id"] = json.Number("121")
		},
		"another format": func(pv map[string]any) {
			pv["format"] = "atomic"
		},
		"an extra preview member": func(pv map[string]any) {
			pv["note"] = "x"
		},
	}
	for name, edit := range cases {
		t.Run(name, func(t *testing.T) {
			resp, _ := mutatePreview(t, fx, edit)
			if verifyOK(resp, fx, input, f) {
				t.Fatal("a precheck that does not bind to the input was accepted")
			}
		})
	}
	t.Run("the preview digest is not the tree's", func(t *testing.T) {
		resp := fixtureResponse(fx, nil)
		resp.PreviewDigest = strings.Repeat("0", 64)
		if verifyOK(resp, fx, input, f) {
			t.Fatal("accepted")
		}
	})
	t.Run("the precheck digest is not the input's", func(t *testing.T) {
		other := strings.Replace(fx.Input, "Open every day", "Open every night", 1)
		g, code := validatePageEditInput([]byte(other))
		if code != "" {
			t.Fatal(code)
		}
		if _, ok := verifyPageEditPrecheck(fixtureResponse(fx, nil), fx.EntrySHA256, []byte(other), g); ok {
			t.Fatal("accepted")
		}
	})
}

func verifyOK(resp agentcmd.AbilityRunResponse, fx pageEditPreviewFixture, input []byte, f pageEditFacts) bool {
	_, ok := verifyPageEditPrecheck(resp, fx.EntrySHA256, input, f)
	return ok
}

// TestPHPHTMLEntityDecode pins the decode the projection's site text uses
// to PHP's html_entity_decode(ENT_QUOTES | ENT_HTML5, 'UTF-8').
func TestPHPHTMLEntityDecode(t *testing.T) {
	cases := map[string]string{
		"Summer sale &amp; more":     "Summer sale & more",
		"&lt;b&gt; &#091;1&#093;":    "<b> [1]",
		"&quot;q&quot; &#39;s&apos;": `"q" 's'`,
		"&nbsp;&rsquo;":              " ’",
		"&amp":                       "&amp",
		"&notit;":                    "&notit;",
		"&#0; &#x0D; &#xFFFE;":       "&#0; &#x0D; &#xFFFE;",
		"&#x1F600;":                  "\U0001F600",
		"&#1114112;":                 "&#1114112;",
		"&semi;":                     ";",
		"a&b":                        "a&b",
	}
	for in, want := range cases {
		if got := phpHTMLEntityDecode(in); got != want {
			t.Errorf("phpHTMLEntityDecode(%q) = %q, want %q", in, got, want)
		}
	}
}
